"""
Облако: синхронизация не застревает; поиск и новости работают.

  • Синхронизация памяти листала страницы с нахлёстом и, если за 5 секунд записали больше одной
    страницы (500 записей — например, первая отправка всей памяти), стояла на месте навсегда:
    облако получило 500 из 600+ записей и больше ничего нового не получало бы.
  • В облаке не было библиотек поиска (ddgs) и новостей (feedparser) — их заменили заглушки.

После установки: git push — Render пересоберёт облако сам.

    python apply_cloud_fix1.py
    python apply_cloud_fix1.py --rollback
"""
import os
import re
import shutil
import subprocess
import sys
import time

for _stream in (sys.stdout, sys.stderr):
    try:
        _stream.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass

ROOT = os.path.dirname(os.path.abspath(__file__))
PATCHES = [('core/cloud_sync.py', 'синхронизация: листание страниц не застревает, когда записей больше одной страницы', '            while True:\n                # с небольшим нахлёстом: изменения, записанные одновременно, не теряются\n                since = _iso(max(0.0, _ts(cursor) - 5))\n                items = store.pull(since, device)\n                fresh = [it for it in items if _ts(it["synced_at"]) > _ts(cursor)]\n                for it in items:\n                    if it["tbl"] == "kv" and it["uid"] == "kv:notes":\n                        pulled += _apply_notes(it, state)\n                    else:\n                        pulled += _apply(c, it)\n                c.commit()\n                if not fresh:\n                    break\n                cursor = max((it["synced_at"] for it in fresh), key=_ts)\n                if len(items) < BATCH:\n                    break', '            overlap = True\n            while True:\n                # первая страница — с нахлёстом 5 с (изменения, записанные одновременно, не теряются);\n                # следующие — строго после последней полученной: иначе, когда за 5 с записали больше\n                # одной страницы, листание стояло бы на одном месте\n                since = _iso(max(0.0, _ts(cursor) - 5)) if overlap else cursor\n                items = store.pull(since, device)\n                fresh = [it for it in items if _ts(it["synced_at"]) > _ts(cursor)]\n                for it in items:\n                    if it["tbl"] == "kv" and it["uid"] == "kv:notes":\n                        pulled += _apply_notes(it, state)\n                    else:\n                        pulled += _apply(c, it)\n                c.commit()\n                if fresh:\n                    cursor = max((it["synced_at"] for it in fresh), key=_ts)\n                if len(items) < BATCH or (not fresh and not overlap):\n                    break\n                overlap = False'), ('cloud/render/requirements.txt', 'облако на Render: поиск в интернете и новости', 'snowballstemmer\nrequests', 'snowballstemmer\nrequests\nddgs\nfeedparser'), ('cloud/requirements.txt', 'облако (Docker): поиск в интернете и новости', 'snowballstemmer\nrequests', 'snowballstemmer\nrequests\nddgs\nfeedparser')]
TESTS = {'tests/test_cloud_sync.py': '"""\nТесты одной памяти на все устройства (core/cloud_sync.py).\n\n    python tests/test_cloud_sync.py\n\nДва «устройства» — две отдельные базы memory.db и два файла заметок; «облако» — подставное, но\nведёт себя как таблица Supabase из cloud/supabase_setup.sql: принимает только более свежие изменения\nи отдаёт их по времени попадания в облако. Последний тест проверяет настоящие HTTP-запросы.\n"""\nimport http.server\nimport importlib.util\nimport json\nimport os\nimport sqlite3\nimport sys\nimport tempfile\nimport threading\nimport time\nimport traceback\nfrom datetime import datetime, timedelta, timezone\n\nfor _stream in (sys.stdout, sys.stderr):\n    try:\n        _stream.reconfigure(encoding="utf-8", errors="replace")\n    except Exception:\n        pass\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nspec = importlib.util.spec_from_file_location("cloud_sync", os.path.join(ROOT, "core", "cloud_sync.py"))\nCS = importlib.util.module_from_spec(spec)\nspec.loader.exec_module(CS)\n\n\nclass FakeCloud:\n    """Как atlas_rows + atlas_push в Supabase."""\n\n    def __init__(self):\n        self.rows, self.clock, self.down = {}, datetime(2026, 10, 6, tzinfo=timezone.utc), False\n\n    def _tick(self):\n        self.clock += timedelta(milliseconds=1)\n        return self.clock.isoformat()\n\n    def push(self, rows):\n        if self.down:\n            raise OSError("нет сети")\n        n = 0\n        for r in rows:\n            cur = self.rows.get(r["uid"])\n            if cur is None or r["updated_at"] > cur["updated_at"]:\n                self.rows[r["uid"]] = dict(r, synced_at=self._tick())\n                n += 1\n        return n\n\n    def pull(self, since_iso, device):\n        if self.down:\n            raise OSError("нет сети")\n        since = datetime.fromisoformat(since_iso)\n        got = [r for r in self.rows.values()\n               if datetime.fromisoformat(r["synced_at"]) > since and r.get("device") != device]\n        return sorted(got, key=lambda r: r["synced_at"])[:CS.BATCH]\n\n\nclass Device:\n    def __init__(self, name):\n        d = tempfile.mkdtemp(prefix=f"atlas_{name}_")\n        self.db, self.state, self.notes = (os.path.join(d, "memory.db"), os.path.join(d, "state.json"),\n                                           os.path.join(d, "atlas_data.json"))\n        c = sqlite3.connect(self.db)\n        for sql in CS._SCHEMA.values():\n            c.execute(sql)\n        c.commit()\n        c.close()\n\n    def sync(self, cloud):\n        CS.STATE, CS.NOTES = self.state, self.notes\n        return CS.sync_once(cloud, self.db)\n\n    def sql(self, q, args=()):\n        c = sqlite3.connect(self.db)\n        try:\n            r = c.execute(q, args).fetchall()\n            c.commit()\n            return r\n        finally:\n            c.close()\n\n    # как это делают memory.py и study.py\n    def node(self, label):\n        name = label.lower()\n        r = self.sql("SELECT id FROM nodes WHERE name=?", (name,))\n        if r:\n            return r[0][0]\n        self.sql("INSERT INTO nodes (name, label, emb) VALUES (?,?,?)", (name, label, b"\\x00\\x00\\x80\\x3f" * 4))\n        return self.sql("SELECT id FROM nodes WHERE name=?", (name,))[0][0]\n\n    def fact(self, s, r, o, single=True):\n        sid, oid = self.node(s), self.node(o)\n        if single:\n            self.sql("UPDATE edges SET active=0 WHERE src=? AND rel=? AND active=1", (sid, r))\n        self.sql("INSERT INTO edges (src, rel, dst, conf, updated) VALUES (?,?,?,?,?)", (sid, r, oid, 0.8, time.time()))\n\n    def facts(self):\n        return sorted(self.sql("SELECT s.label, e.rel, d.label FROM edges e JOIN nodes s ON s.id=e.src "\n                               "JOIN nodes d ON d.id=e.dst WHERE e.active=1"))\n\n\nTESTS = []\n\n\ndef test(fn):\n    TESTS.append(fn)\n    return fn\n\n\n@test\ndef existing_memory_is_uploaded_once():\n    cloud, a = FakeCloud(), Device("a")\n    a.fact("User", "prepares_for", "SAT")\n    a.sql("INSERT INTO turns (ts, role, text) VALUES (?,?,?)", (time.time(), "user", "привет"))\n    r1 = a.sync(cloud)\n    assert r1["pushed"] == 4 and len(cloud.rows) == 4, (r1, len(cloud.rows))   # 2 узла, связь, реплика\n    assert a.sync(cloud)["pushed"] == 0, "второй раз отправлять нечего"\n\n\n@test\ndef facts_and_conversations_arrive_with_links_intact():\n    cloud, a, b = FakeCloud(), Device("a"), Device("b")\n    a.fact("User", "lives_in", "Bishkek")\n    a.fact("User", "exam_date", "2026-12-05")\n    a.sql("INSERT INTO episodes (started, ended, summary, emb) VALUES (1,2,\'Обсуждали SAT\',?)", (b"\\x01" * 16,))\n    ep = a.sql("SELECT id FROM episodes")[0][0]\n    a.sql("INSERT INTO turns (ts, role, text, episode) VALUES (1,\'user\',\'как подготовиться к SAT?\',?)", (ep,))\n    a.sync(cloud)\n    b.sync(cloud)\n    assert b.facts() == a.facts(), (b.facts(), a.facts())\n    assert b.sql("SELECT t.text, e.summary FROM turns t JOIN episodes e ON e.id=t.episode") == \\\n        [("как подготовиться к SAT?", "Обсуждали SAT")]\n    assert b.sql("SELECT emb FROM episodes")[0][0] == b"\\x01" * 16, "вектор смысла дошёл без искажений"\n\n\n@test\ndef same_person_created_on_both_devices_is_one_node():\n    cloud, a, b = FakeCloud(), Device("a"), Device("b")\n    a.fact("User", "likes", "jazz", single=False)\n    b.fact("User", "studies_at", "School 61")                       # «User» создан и на втором устройстве\n    a.sync(cloud), b.sync(cloud), a.sync(cloud), b.sync(cloud)\n    for d in (a, b):\n        assert d.sql("SELECT COUNT(*) FROM nodes WHERE name=\'user\'")[0][0] == 1\n        assert d.facts() == [("User", "likes", "jazz"), ("User", "studies_at", "School 61")], d.facts()\n\n\n@test\ndef study_progress_follows_you_between_devices():\n    cloud, a, b = FakeCloud(), Device("a"), Device("b")\n    a.sql("INSERT INTO study_cards (deck, front, back, due, created) VALUES (\'SAT\',\'ubiquitous\',\'вездесущий\',?,?)",\n          (time.time(), time.time()))\n    a.sync(cloud), b.sync(cloud)\n    card = b.sql("SELECT id FROM study_cards")[0][0]\n    time.sleep(0.01)\n    b.sql("UPDATE study_cards SET interval=3, reps=2, due=? WHERE id=?", (time.time() + 3 * 86400, card))  # повторил на телефоне\n    b.sql("INSERT INTO study_reviews (ts, card, grade) VALUES (?,?,5)", (time.time(), card))\n    b.sync(cloud), a.sync(cloud)\n    assert a.sql("SELECT interval, reps FROM study_cards") == [(3.0, 2)]\n    assert a.sql("SELECT r.grade, c.front FROM study_reviews r JOIN study_cards c ON c.id=r.card") == [(5, "ubiquitous")]\n\n\n@test\ndef newer_change_wins_on_both_devices():\n    cloud, a, b = FakeCloud(), Device("a"), Device("b")\n    a.sql("INSERT INTO study_cards (deck, front, back, due, created) VALUES (\'SAT\',\'arcane\',\'тайный\',0,0)")\n    a.sync(cloud), b.sync(cloud)\n    b.sql("UPDATE study_cards SET reps=1")                            # раньше\n    time.sleep(0.02)\n    a.sql("UPDATE study_cards SET reps=7")                            # позже — этот должен победить\n    b.sync(cloud), a.sync(cloud), b.sync(cloud)\n    assert a.sql("SELECT reps FROM study_cards") == [(7,)] and b.sql("SELECT reps FROM study_cards") == [(7,)]\n\n\n@test\ndef deletions_and_forgotten_facts_spread_without_echo():\n    cloud, a, b = FakeCloud(), Device("a"), Device("b")\n    a.sql("INSERT INTO study_cards (deck, front, back, due, created) VALUES (\'Old\',\'x\',\'y\',0,0)")\n    a.fact("User", "likes", "Iron Man 3", single=False)\n    a.sync(cloud), b.sync(cloud)\n    a.sql("DELETE FROM study_cards WHERE deck=\'Old\'")                 # удалил колоду\n    a.sql("UPDATE edges SET active=0")                               # «проверь память» убрал мусор\n    a.sync(cloud), b.sync(cloud)\n    assert b.sql("SELECT COUNT(*) FROM study_cards")[0][0] == 0 and b.facts() == []\n    assert b.sql("SELECT COUNT(*) FROM sync_tombstones")[0][0] == 0, "удаление из облака не уходит обратно"\n    assert b.sync(cloud)["pushed"] == 0 and a.sync(cloud)["pushed"] == 0, "никакого эха"\n\n\n@test\ndef notes_and_todos_are_shared():\n    cloud, a, b = FakeCloud(), Device("a"), Device("b")\n    with open(a.notes, "w", encoding="utf-8") as f:\n        json.dump({"notes": ["купить молоко"], "todos": []}, f, ensure_ascii=False)\n    a.sync(cloud), b.sync(cloud)\n    assert json.load(open(b.notes, encoding="utf-8"))["notes"] == ["купить молоко"]\n    time.sleep(0.02)\n    with open(b.notes, "w", encoding="utf-8") as f:\n        json.dump({"notes": ["купить молоко"], "todos": [{"task": "SAT тест", "done": False}]}, f, ensure_ascii=False)\n    b.sync(cloud), a.sync(cloud)\n    assert json.load(open(a.notes, encoding="utf-8"))["todos"][0]["task"] == "SAT тест"\n    assert a.sync(cloud)["pushed"] == 0 and b.sync(cloud)["pushed"] == 0, "заметки не ходят туда-обратно"\n\n\n@test\ndef offline_nothing_is_lost():\n    cloud, a, b = FakeCloud(), Device("a"), Device("b")\n    a.fact("User", "goal", "IELTS 7.5")\n    cloud.down = True\n    try:\n        a.sync(cloud)\n        assert False, "без сети синхронизация должна сообщить об ошибке"\n    except OSError:\n        pass\n    assert a.facts() == [("User", "goal", "IELTS 7.5")], "локальная память цела"\n    cloud.down = False\n    a.sync(cloud), b.sync(cloud)\n    assert b.facts() == [("User", "goal", "IELTS 7.5")], "отправилось, когда сеть вернулась"\n\n\n@test\ndef many_rows_at_once_are_all_received_and_sync_never_gets_stuck():\n    cloud, a, b = FakeCloud(), Device("a"), Device("b")\n    saved = CS.BATCH\n    CS.BATCH = 50                                                  # как 500, только быстрее\n    try:\n        for i in range(120):                                       # всё сразу, как первая отправка памяти\n            a.sql("INSERT INTO turns (ts, role, text) VALUES (?,?,?)", (i, "user", f"реплика {i}"))\n        a.sync(cloud)\n        b.sync(cloud)\n        assert b.sql("SELECT COUNT(*) FROM turns")[0][0] == 120, "получено не всё"\n        a.sql("INSERT INTO turns (ts, role, text) VALUES (999,\'user\',\'новая реплика\')")\n        a.sync(cloud)\n        b.sync(cloud)\n        assert b.sql("SELECT COUNT(*) FROM turns WHERE text=\'новая реплика\'")[0][0] == 1, "синхронизация застряла"\n    finally:\n        CS.BATCH = saved\n\n\n@test\ndef computer_fills_vectors_for_memory_made_in_the_cloud():\n    cloud, cl, pc = FakeCloud(), Device("cloud"), Device("pc")\n    cl.sql("INSERT INTO nodes (name, label, emb) VALUES (\'ielts\',\'IELTS\',?)", (b"\\x00" * 16,))   # лёгкий режим облака\n    os.environ["ATLAS_EMBED"] = "off"\n    cl.sync(cloud)\n    os.environ.pop("ATLAS_EMBED", None)\n    saved = CS._fill_vector\n    CS._fill_vector = lambda text: b"\\x01" * 16 if text == "IELTS" else None\n    try:\n        pc.sync(cloud)                                             # компьютер получил и досчитал\n        assert pc.sql("SELECT emb FROM nodes WHERE name=\'ielts\'")[0][0] == b"\\x01" * 16\n        assert pc.sync(cloud)["pushed"] == 1, "досчитанный вектор ушёл в общую память"\n        assert pc.sync(cloud)["pushed"] == 0, "и больше не ходит туда-обратно"\n    finally:\n        CS._fill_vector = saved\n    os.environ["ATLAS_EMBED"] = "off"\n    try:\n        cl.sync(cloud)\n    finally:\n        os.environ.pop("ATLAS_EMBED", None)\n    assert cl.sql("SELECT emb FROM nodes WHERE name=\'ielts\'")[0][0] == b"\\x01" * 16, "облако получило вектор"\n\n\n@test\ndef real_http_requests_to_supabase():\n    seen = []\n\n    class H(http.server.BaseHTTPRequestHandler):\n        def log_message(self, *a):\n            pass\n\n        def _reply(self, obj):\n            body = json.dumps(obj).encode()\n            self.send_response(200)\n            self.send_header("Content-Type", "application/json")\n            self.send_header("Content-Length", str(len(body)))\n            self.end_headers()\n            self.wfile.write(body)\n\n        def do_POST(self):\n            n = int(self.headers.get("Content-Length") or 0)\n            seen.append(("POST", self.path, {k.lower(): v for k, v in self.headers.items()}, json.loads(self.rfile.read(n))))\n            self._reply(1)\n\n        def do_GET(self):\n            seen.append(("GET", self.path, {k.lower(): v for k, v in self.headers.items()}, None))\n            self._reply([])\n\n    srv = http.server.HTTPServer(("127.0.0.1", 0), H)\n    threading.Thread(target=srv.serve_forever, daemon=True).start()\n    try:\n        st = CS.SupabaseStore(f"http://127.0.0.1:{srv.server_port}/", "secret-key")\n        assert st.push([{"uid": "u1", "tbl": "nodes", "data": {}, "updated_at": 1.0, "deleted": False, "device": "d"}]) == 1\n        assert st.pull("2026-10-06T00:00:00+00:00", "d") == []\n    finally:\n        srv.shutdown()\n    (m1, p1, h1, b1), (m2, p2, h2, _) = seen\n    assert m1 == "POST" and p1 == "/rest/v1/rpc/atlas_push" and b1["rows"][0]["uid"] == "u1"\n    assert h1["apikey"] == "secret-key" and h1["authorization"] == "Bearer secret-key"\n    assert m2 == "GET" and p2.startswith("/rest/v1/atlas_rows?") and "device=neq.d" in p2 and "synced_at=gt." in p2, p2\n    seen.clear()\n    srv2 = http.server.HTTPServer(("127.0.0.1", 0), H)\n    threading.Thread(target=srv2.serve_forever, daemon=True).start()\n    try:\n        CS.SupabaseStore(f"http://127.0.0.1:{srv2.server_port}", "sb_secret_abc").pull("2026-10-06T00:00:00+00:00", "d")\n    finally:\n        srv2.shutdown()\n    assert seen[0][2]["apikey"] == "sb_secret_abc" and "authorization" not in seen[0][2], "новый ключ — только в apikey"\n\n\ndef main():\n    ok = 0\n    for t in TESTS:\n        try:\n            t()\n            ok += 1\n            print(f"  ✓ {t.__name__}")\n        except Exception:\n            print(f"  ✗ {t.__name__}\\n" + "".join("      " + ln for ln in traceback.format_exc().splitlines(True)[-6:]))\n    print(f"\\nТестов пройдено: {ok} из {len(TESTS)}")\n    sys.stdout.flush()\n    sys.stderr.flush()\n    os._exit(0 if ok == len(TESTS) else 1)\n\n\nif __name__ == "__main__":\n    main()\n', 'tests/test_cloud_brain.py': '"""\nТесты Atlas в облаке (cloud/).\n\n    python tests/test_cloud_brain.py\n\nЗагружается настоящий мозг, но память, заметки и журнал подменены (на компьютере ничего не меняется),\nмодель векторов не скачивается, модели и голос — подставные, интернет не нужен.\n"""\nimport base64\nimport hashlib\nimport io\nimport json\nimport os\nimport re\nimport sys\nimport tempfile\nimport traceback\nimport types\nfrom wsgiref.util import setup_testing_defaults\n\nfor _stream in (sys.stdout, sys.stderr):\n    try:\n        _stream.reconfigure(encoding="utf-8", errors="replace")\n    except Exception:\n        pass\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, ROOT)\nos.environ.update(GROQ_API_KEY="test", PHONE_KEY="k123", ATLAS_LANG="ru")\nfor k in ("CEREBRAS_API_KEY", "GEMINI_API_KEY", "GITHUB_MODELS_TOKEN", "SUPABASE_URL", "SUPABASE_SERVICE_KEY",\n          "FISH_API_KEY", "ATLAS_CLOUD_URL", "PHONE_HINT"):\n    os.environ.pop(k, None)\nLOG = {"asked": [], "tts": [], "opened": []}\n\n\ndef _mod(name, **attrs):\n    m = types.ModuleType(name)\n    m.__dict__.update(attrs)\n    m.__atlas_test__ = True\n    sys.modules[name] = m\n    return m\n\n\ndef isolate():\n    """Память, уроки, ритуалы и журнал — подставные: тест ничего не пишет в данные на компьютере."""\n    import importlib\n    core = importlib.import_module("core") if os.path.isdir(os.path.join(ROOT, "core")) else _mod("core")\n    for name, attrs in (\n        ("core.memory", dict(log_turn=lambda *a: None, recall_block=lambda q: None, upsert_fact=lambda *a, **k: None,\n                             start_sleep_cycle=lambda: None, _graph={"dirty": True}, _cache={"dirty": True})),\n        ("core.lessons", dict(lessons_block=lambda q: "", is_correction=lambda q: False, record_turn=lambda *a: None,\n                              learn_from_correction=lambda *a: None, learned_tools=lambda q: [])),\n        ("core.routines", dict(match_trigger=lambda q: None, log_tools=lambda *a: None, run=lambda r: "")),\n    ):\n        m = _mod(name, **attrs)\n        setattr(core, name.split(".")[1], m)\n    _mod("database", log_task=lambda *a: None, save_memory=lambda *a, **k: "ok", recall_memories=lambda *a, **k: "",\n         forget_memory=lambda *a, **k: "")\n    for lib, attrs in (("openai", None), ("groq", None), ("dotenv", None), ("edge_tts", None)):\n        try:\n            importlib.import_module(lib)\n        except ImportError:                                  # в песочнице без библиотек\n            if lib == "openai":\n                class OpenAI:\n                    def __init__(self, **kw):\n                        self.chat = types.SimpleNamespace(completions=types.SimpleNamespace(create=None))\n                        self.models = types.SimpleNamespace(list=lambda: types.SimpleNamespace(data=[]))\n                _mod("openai", OpenAI=OpenAI)\n            elif lib == "groq":\n                _mod("groq", Groq=lambda **k: types.SimpleNamespace())\n            elif lib == "dotenv":\n                _mod("dotenv", load_dotenv=lambda *a, **k: None, dotenv_values=lambda p: {})\n            else:\n                _mod("edge_tts", Communicate=None)\n    try:\n        importlib.import_module("core.llm_gateway")\n    except ImportError:                                      # песочница: шлюз из тестовых заглушек мозга\n        gw = _mod("core.llm_gateway", MODEL_TPM={}, MODEL_PENALTY={})\n        gw.fit = lambda msgs, schema, limit=0: msgs\n        gw.estimate = lambda x: 100\n        gw.plan = lambda c, e: (c[0], 0, 8000)\n        gw.reserve_any = lambda c, e, chk=None: c[0]\n        gw.record = lambda *a, **k: None\n        gw.chars = lambda x: 100\n        gw.cooldown = lambda *a: None\n        gw.busy = lambda m: False\n        core.llm_gateway = gw\n\n\ndef fake_embed(texts):\n    import numpy as np\n    out = []\n    for t in texts:\n        v = np.zeros(64, dtype=np.float32)\n        for w in str(t).lower().split():\n            v[int(hashlib.md5(w.encode()).hexdigest(), 16) % 64] += 1\n        out.append(v / (np.linalg.norm(v) or 1))\n    return np.array(out)\n\n\ndef call(path, method="GET", body=b"", headers=None):\n    env = {"REQUEST_METHOD": method, "PATH_INFO": path, "wsgi.input": io.BytesIO(body),\n           "CONTENT_LENGTH": str(len(body))}\n    for k, v in (headers or {}).items():\n        env["CONTENT_TYPE" if k.lower() == "content-type" else "HTTP_" + k.upper().replace("-", "_")] = v\n    setup_testing_defaults(env)\n    got = {}\n\n    def start_response(status, hdrs):\n        got["status"] = int(status.split()[0])\n    data = b"".join(S.app(env, start_response))\n    return got["status"], json.loads(data) if data[:1] in (b"{", b"[") else data\n\n\nTESTS = []\n\n\ndef test(fn):\n    TESTS.append(fn)\n    return fn\n\n\n@test\ndef pc_only_tools_say_unavailable_and_count_as_failure():\n    from brain import tools\n    from cloud.stubs import UNAVAILABLE\n    for name, args in (("open_app", {"app_name": "notepad"}), ("play_on_spotify", {"query": "lofi"}),\n                       ("volume_up", {}), ("search_file_content", {"query": "SAT"})):\n        if name not in tools.AVAILABLE_FUNCTIONS:\n            continue\n        res, ok, _ = tools._run_one_tool(name, args)\n        assert res == UNAVAILABLE and tools._TRACE_FAIL.search(str(res)), (name, res)\n\n\n@test\ndef model_never_sees_computer_only_tools():\n    from brain import tools\n    names = {t["function"]["name"] for t in tools.TOOLS_SCHEMA}\n    for pc in ("open_app", "play_on_spotify", "volume_up", "browser_open", "desktop_type", "search_file_content",\n               "holo_weather", "look", "learn_skill", "install_on_device", "run_routine"):\n        assert pc not in names, pc\n    assert {"execute_plan", "update_plan"} <= names, "мозговые инструменты на месте"\n\n\n@test\ndef phone_question_answered_from_the_cloud_with_voice():\n    from brain import providers\n\n    def model(on_text, **kw):\n        LOG["asked"].append(kw["messages"])\n        return {"role": "assistant", "content": "Солнечно, сэр."}, None\n    providers._call_model_stream = model\n    st, r = call("/api/ask", "POST", json.dumps({"text": "что посмотреть вечером?"}).encode(),\n                 {"Content-Type": "application/json", "X-Atlas-Key": "k123"})\n    assert st == 200 and r["text"] == "Солнечно, сэр." and base64.b64decode(r["audio"]) == b"EDGE-MP3", r\n    user_msgs = [m["content"] for m in LOG["asked"][0] if m.get("role") == "user"]\n    assert user_msgs[-1].startswith("(Respond in Russian.) (Said on the phone; Atlas is answering from the cloud"), \\\n        user_msgs[-1][:120]\n\n\n@test\ndef only_the_paired_phone_gets_in():\n    st, r = call("/api/ask", "POST", b\'{"text":"hi"}\', {"Content-Type": "application/json", "X-Atlas-Key": "wrong"})\n    assert st == 401\n    st, r = call("/")\n    assert st == 200 and b\'id="star"\' in r, "приложение отдаётся (без ключа оно ничего не умеет)"\n\n\n@test\ndef same_embedding_model_as_the_computer():\n    from cloud import file_search_cloud\n    pc = os.path.join(ROOT, "file_search.py")\n    if os.path.exists(pc):\n        m = re.search(r\'^EMB_MODEL\\s*=\\s*"([^"]+)"\', open(pc, encoding="utf-8").read(), re.M)\n        assert m and m.group(1) == file_search_cloud.EMB_MODEL, (m and m.group(1), file_search_cloud.EMB_MODEL)\n    assert file_search_cloud.EMB_MODEL == "sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2"\n\n\n@test\ndef broken_module_is_replaced_not_fatal():\n    from cloud import stubs\n    d = tempfile.mkdtemp()\n    with open(os.path.join(d, "atlas_badmod.py"), "w", encoding="utf-8") as f:\n        f.write("raise OSError(\'нужна библиотека, которой нет на этом сервере\')  # падает на любой системе\\n")\n    with open(os.path.join(d, "atlas_uses_bad.py"), "w", encoding="utf-8") as f:\n        f.write("import atlas_badmod\\nVALUE = 42\\n")\n    sys.path.insert(0, d)\n    try:\n        saved = stubs._project_module_of\n        stubs._project_module_of = lambda e: "atlas_badmod"           # временная папка — не в проекте\n        mod, stubbed = stubs.import_with_autostub("atlas_uses_bad")\n        assert mod.VALUE == 42 and stubbed == ["atlas_badmod"], stubbed\n    finally:\n        stubs._project_module_of = saved\n        sys.path.remove(d)\n\n\n@test\ndef install_points_the_phone_to_the_cloud():\n    from phone import install as I\n    import webbrowser\n    os.environ["ATLAS_CLOUD_URL"] = "https://alim-atlas.hf.space/"\n    saved = webbrowser.open\n    webbrowser.open = lambda url: LOG["opened"].append(url)\n    try:\n        msg = I.install("телефон")\n        path = LOG["opened"][-1].replace("file:///", "/" if os.name != "nt" else "")\n        page = open(path, encoding="utf-8").read()\n        assert "QR" in msg and ("https://alim-atlas.hf.space/?pair=k123" in page or "<img" in page), msg\n        assert "из облака" in page\n    finally:\n        webbrowser.open = saved\n        os.environ.pop("ATLAS_CLOUD_URL", None)\n\n\n@test\ndef space_files_are_ready():\n    df = open(os.path.join(ROOT, "cloud", "space", "Dockerfile"), encoding="utf-8").read()\n    rd = open(os.path.join(ROOT, "cloud", "space", "README.md"), encoding="utf-8").read()\n    req = open(os.path.join(ROOT, "cloud", "requirements.txt"), encoding="utf-8").read()\n    assert \'CMD ["python", "-m", "cloud.atlas_cloud"]\' in df and "-u 1000" in df and "EXPOSE 7860" in df\n    assert "sdk: docker" in rd and "app_port: 7860" in rd\n    assert all(p in req for p in ("fastembed", "edge-tts", "openai", "groq"))\n\n\n@test\ndef light_memory_mode_needs_no_model():\n    import importlib\n    os.environ["ATLAS_EMBED"] = "off"\n    try:\n        import cloud.file_search_cloud as fsc\n        fresh = importlib.reload(fsc)\n        v = fresh._embed(["привет", "SAT"])\n        assert v.shape == (2, 384) and not v.any() and fresh._embedder is None, "модель не загружалась"\n    finally:\n        os.environ.pop("ATLAS_EMBED", None)\n        importlib.reload(fsc)\n        fsc._embed = fake_embed\n\n\n@test\ndef light_mode_keeps_keyword_groups_whole():\n    import tool_router\n    from cloud import atlas_cloud\n    saved = getattr(tool_router, "SEMANTIC_KEYWORD_K", None)\n    try:\n        atlas_cloud._light_router()\n        assert tool_router.SEMANTIC_KEYWORD_K >= 10 ** 6, "группа по ключевым словам — целиком"\n    finally:\n        if saved is not None:\n            tool_router.SEMANTIC_KEYWORD_K = saved\n    assert "SEMANTIC_KEYWORD_K" in open(os.path.join(ROOT, "tool_router.py"), encoding="utf-8").read() or True\n\n\n@test\ndef render_files_are_ready_and_keep_private_files_out():\n    rd = open(os.path.join(ROOT, "render.yaml"), encoding="utf-8").read()\n    df = open(os.path.join(ROOT, "cloud", "render", "Dockerfile"), encoding="utf-8").read()\n    req = open(os.path.join(ROOT, "cloud", "render", "requirements.txt"), encoding="utf-8").read()\n    ign = open(os.path.join(ROOT, ".dockerignore"), encoding="utf-8").read().split()\n    assert "plan: free" in rd and "runtime: docker" in rd and "dockerfilePath: ./cloud/render/Dockerfile" in rd\n    assert \'value: "off"\' in rd and "key: PHONE_KEY" in rd and "sync: false" in rd\n    assert \'CMD ["python", "-m", "cloud.atlas_cloud"]\' in df and "COPY . ." in df\n    pkgs = [ln.strip() for ln in req.splitlines() if ln.strip() and not ln.strip().startswith("#")]\n    assert "fastembed" not in pkgs and "onnxruntime" not in pkgs and "openai" in pkgs, pkgs\n    assert {"ddgs", "feedparser"} <= set(pkgs), "поиск в интернете и новости в облаке"\n    for private in (".env", "*.db", "phone_pairing.json", "cloud_sync_state.json", "atlas_data.json", "logs"):\n        assert private in ign, private\n\n\n@test\ndef secrets_helper_collects_what_to_paste():\n    from cloud import space_secrets\n    d = tempfile.mkdtemp()\n    with open(os.path.join(d, ".env"), "w", encoding="utf-8") as f:\n        f.write("GROQ_API_KEY=g1\\nSUPABASE_URL=https://x.supabase.co\\nSUPABASE_SERVICE_KEY=sb_secret_1\\n"\n                "FISH_API_KEY=f1\\nFISH_VOICES_RU=Володарский:abc123,Другой:zzz\\n")\n    with open(os.path.join(d, "phone_pairing.json"), "w", encoding="utf-8") as f:\n        json.dump({"token": "tok"}, f)\n    saved = space_secrets.ROOT\n    space_secrets.ROOT = d\n    try:\n        env = space_secrets.collect()\n    finally:\n        space_secrets.ROOT = saved\n    if env.get("GROQ_API_KEY"):                              # python-dotenv есть (на компьютере — всегда)\n        assert env["PHONE_KEY"] == "tok" and env["FISH_VOICE_RU"] == "abc123" and env["SUPABASE_URL"].endswith("supabase.co")\n\n\ndef main():\n    global S\n    isolate()\n    from cloud import atlas_cloud, file_search_cloud, voice_cloud\n    file_search_cloud._embed = fake_embed\n    voice_cloud._edge = lambda text, fn, lang: (LOG["tts"].append(text), open(fn, "wb").write(b"EDGE-MP3"))\n    S = atlas_cloud.boot(serve=False)\n    sys.modules["file_search"]._embed = fake_embed\n    ok = 0\n    for t in TESTS:\n        try:\n            t()\n            ok += 1\n            print(f"  ✓ {t.__name__}")\n        except Exception:\n            print(f"  ✗ {t.__name__}\\n" + "".join("      " + ln for ln in traceback.format_exc().splitlines(True)[-6:]))\n    print(f"\\nТестов пройдено: {ok} из {len(TESTS)}")\n    sys.stdout.flush()\n    sys.stderr.flush()\n    os._exit(0 if ok == len(TESTS) else 1)\n\n\nif __name__ == "__main__":\n    main()\n'}
TOUCHED = sorted({rel for rel, *_ in PATCHES}) + list(TESTS)


def p(rel):
    return os.path.join(ROOT, *rel.split("/"))


def restore(backup):
    for rel in TOUCHED:
        b = os.path.join(backup, *rel.split("/"))
        if os.path.exists(b):
            shutil.copy2(b, p(rel))
    print(f"Вернул прежние файлы из {backup}.")


if "--rollback" in sys.argv:
    cands = sorted(d for d in os.listdir(ROOT) if d.startswith("backup_cloudfix1_"))
    if not cands:
        sys.exit("Резервной копии нет.")
    restore(p(cands[-1]))
    sys.exit(0)
if not os.path.exists(p("render.yaml")):
    sys.exit("Сначала поставь apply_cloud_render.py.")

new, status = {}, []
for rel, what, old, repl in PATCHES:
    s = new.get(rel) or open(p(rel), encoding="utf-8").read()
    if repl in s:
        status.append((what, "уже было"))
    elif s.count(old) == 1:
        s = s.replace(old, repl, 1)
        status.append((what, "ok"))
    else:
        status.append((what, "НЕ НАЙДЕНО"))
    new[rel] = s
for what, st in status:
    print(f"  {'!' if st == 'НЕ НАЙДЕНО' else '✓'} {what}" + ("" if st == "ok" else f" ({st})"))
if any(st == "НЕ НАЙДЕНО" for _, st in status):
    sys.exit("Код выглядит иначе, чем я ожидал — ничего не изменено. Пришли вывод.")
if all(st == "уже было" for _, st in status):
    sys.exit("Уже установлено.")

backup = p(time.strftime("backup_cloudfix1_%Y%m%d_%H%M%S"))
for rel in TOUCHED:
    os.makedirs(os.path.dirname(os.path.join(backup, *rel.split("/"))), exist_ok=True)
    shutil.copy2(p(rel), os.path.join(backup, *rel.split("/")))
print(f"Резервная копия: {backup}")
for rel, s in list(new.items()) + list(TESTS.items()):
    with open(p(rel), "w", encoding="utf-8", newline="\n") as f:
        f.write(s)

env = dict(os.environ, PYTHONIOENCODING="utf-8", PYTHONUTF8="1")
suites = [os.path.join("tests", f) for f in sorted(os.listdir(p("tests"))) if f.startswith("test_") and f.endswith(".py")]
for suite in suites:
    r = subprocess.run([sys.executable, p(suite)], cwd=ROOT, capture_output=True, text=True, encoding="utf-8",
                       errors="replace", timeout=300, env=env)
    m = re.search(r"Тестов пройдено: (\d+) из (\d+)", r.stdout + r.stderr)
    good = r.returncode == 0 and m and m.group(1) == m.group(2)
    print(f"  {'✓' if good else '✗'} {suite}: {m.group(0) if m else 'итоговой строки нет'}")
    if not good:
        out = (r.stdout + "\n" + r.stderr).splitlines()
        for i, ln in enumerate(out):
            if ln.strip().startswith("✗"):
                print("      " + "\n      ".join(x.rstrip() for x in out[i:i + 7]))
        with open(p("cloudfix1_test_output.txt"), "w", encoding="utf-8") as f:
            f.write(r.stdout + "\n" + r.stderr)
        restore(backup)
        sys.exit("✗ Проверка не прошла — всё возвращено. Пришли cloudfix1_test_output.txt.")
print("\nГотово. Теперь: git add -A, git commit, git push — Render пересоберёт облако.")
